export function notesFor(sample,river,local=true){if(river!=='ganga'||!sample?.chapter.scene)return [];return (sample.travelling?travelNotes:local?locationNotes:mapNotes)[sample.chapter.scene]||[];}
export const playbackSpeeds=[.5,1,1.5,2,3];
export function noteIndex(phase,count){return Math.max(0,Math.min(count-1,Math.floor(Math.max(0,phase)*count)));}
